SELECT version, version_full FROM v$instance;

SELECT description, TO_CHAR(action_time,'YYYY-MM-DD') AS aplicado_em
FROM dba_registry_sqlpatch ORDER BY action_time DESC FETCH FIRST 5 ROWS ONLY;

SELECT name, state, total_mb, free_mb,
       ROUND((1-free_mb/NULLIF(total_mb,0))*100,2) AS pct_usado
FROM v$asm_diskgroup ORDER BY pct_usado DESC;
